  const isStageUnlocked = (stageId: number): boolean => {
    if (isAdvancedMode || stageId === 1) return true;
    return stageCompletions[stageId - 2] >= 70;
  };

  const navigateTo = (sectionId: string) => {
    const stageId = SECTION_TO_STAGE[sectionId] ?? 1;
