1	import { useState } from "react";
2	import {
3	  useCreateEntity, useUpdateEntity, useDeleteEntity, useAiGenerateEntities,
4	  getListEntitiesQueryKey, type Entity,
5	} from "@workspace/api-client-react";
6	import { useQueryClient } from "@tanstack/react-query";
7	import { useToast } from "@/hooks/use-toast";
8	import { Button } from "@/components/ui/button";
9	import { Input } from "@/components/ui/input";
10	import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
11	import { Label } from "@/components/ui/label";
12	import { Plus, Trash2, Loader2, Sparkles, X, Download, Hash } from "lucide-react";
13	
14	const CARD_SUBTYPES = ["Action", "Item", "Spell", "Event", "Quest", "Encounter", "Treasure", "Attack", "Defense", "Custom"];
15	
16	function exportDeckCSV(deckName: string, cards: Entity[]) {
17	  const headers = ["Name", "Subtype", "Effect / Rules Text", "Flavor Text", "Designer Notes"];
18	  const rows = cards.map(c => [
19	    c.name,
20	    c.subtype ?? "",
21	    (c.description ?? "").replace(/"/g, '""'),
22	    (c.lore ?? "").replace(/"/g, '""'),
23	    (c.designNotes ?? "").replace(/"/g, '""'),
24	  ]);
25	  const csv = [headers, ...rows].map(r => r.map(v => `"${v}"`).join(",")).join("\n");
26	  const blob = new Blob([csv], { type: "text/csv" });
27	  const url = URL.createObjectURL(blob);
28	  const a = document.createElement("a");
29	  a.href = url;
30	  a.download = `${deckName.replace(/\W+/g, "_")}_cards.csv`;
31	  a.click();
32	  URL.revokeObjectURL(url);
33	}
34	
35	interface CardStudioProps {
36	  projectId: number;
37	  deck: Entity;
38	  cards: Entity[];
39	  onRefresh: () => void;
40	}
41	
42	export function CardStudio({ projectId, deck, cards, onRefresh }: CardStudioProps) {
43	  const qc = useQueryClient();
44	  const { toast } = useToast();
45	  const createEntity = useCreateEntity();
46	  const updateEntity = useUpdateEntity();
47	  const deleteEntity = useDeleteEntity();
48	  const aiGenerate = useAiGenerateEntities();
49	
50	  type EditCell = { cardId: number; field: "name" | "description" | "lore" };
51	  const [editingCell, setEditingCell] = useState<EditCell | null>(null);
52	  const [editValue, setEditValue] = useState("");
53	  const [saving, setSaving] = useState(false);
54	
55	  const [newCard, setNewCard] = useState({ name: "", subtype: "", description: "", lore: "" });
56	  const [showAddForm, setShowAddForm] = useState(false);
57	  const [showAI, setShowAI] = useState(false);
58	  const [aiPrompt, setAiPrompt] = useState("");
59	  const [aiCount, setAiCount] = useState(5);
60	  const [generating, setGenerating] = useState(false);
61	
62	  const startEdit = (cardId: number, field: EditCell["field"], value: string) => {
63	    setEditingCell({ cardId, field });
64	    setEditValue(value);
65	  };
66	
67	  const commitEdit = async () => {
68	    if (!editingCell || saving) return;
69	    setSaving(true);
70	    try {
71	      await updateEntity.mutateAsync({
72	        projectId,
73	        entityId: editingCell.cardId,
74	        data: { [editingCell.field]: editValue || undefined } as Parameters<typeof updateEntity.mutateAsync>[0]["data"],
75	      });
76	      onRefresh();
77	    } catch {
78	      toast({ title: "Update failed", variant: "destructive" });
79	    } finally {
80	      setSaving(false);
81	      setEditingCell(null);
82	    }
83	  };
84	
85	  const handleAddCard = async () => {
86	    if (!newCard.name.trim()) return;
87	    try {
88	      await createEntity.mutateAsync({
89	        projectId,
90	        data: {
91	          name: newCard.name.trim(),
92	          type: "Card",
93	          subtype: newCard.subtype || undefined,
94	          description: newCard.description || undefined,
95	          lore: newCard.lore || undefined,
96	          parentEntityId: deck.id,
97	        },
98	      });
99	      setNewCard({ name: "", subtype: "", description: "", lore: "" });
100	      setShowAddForm(false);
101	      onRefresh();
102	    } catch {
103	      toast({ title: "Could not add card", variant: "destructive" });
104	    }
105	  };
106	
107	  const handleDelete = async (id: number, name: string) => {
108	    if (!confirm(`Remove "${name}" from deck?`)) return;
109	    try {
110	      await deleteEntity.mutateAsync({ projectId, entityId: id });
111	      onRefresh();
112	    } catch {
113	      toast({ title: "Delete failed", variant: "destructive" });
114	    }
115	  };
116	
117	  const handleAIGenerate = async () => {
118	    if (!aiPrompt) return;
119	    setGenerating(true);
120	    const beforeIds = new Set(cards.map(c => c.id));
121	    try {
122	      const fullPrompt = `Generate ${aiCount} cards for the deck "${deck.name}" (${deck.subtype ?? "custom deck"}). ${aiPrompt}. Each should be type "Card" with a clear name, subtype, rules-text description, and optional flavor text.`;
123	      await aiGenerate.mutateAsync({ projectId, data: { prompt: fullPrompt, count: aiCount } });
124	      // Refetch and auto-assign any new Card entities without a parent to this deck
125	      qc.invalidateQueries({ queryKey: getListEntitiesQueryKey(projectId) });
126	      await new Promise(r => setTimeout(r, 600));
127	      const freshKey = getListEntitiesQueryKey(projectId);
128	      const cached = qc.getQueryData<Entity[]>(freshKey) ?? [];
129	      const newCards = cached.filter(e => e.type === "Card" && !e.parentEntityId && !beforeIds.has(e.id));
130	      if (newCards.length > 0) {
131	        await Promise.all(newCards.map(c =>
132	          updateEntity.mutateAsync({ projectId, entityId: c.id, data: { parentEntityId: deck.id } })
133	        ));
134	      }
135	      setAiPrompt("");
136	      setShowAI(false);
137	      onRefresh();
138	      toast({ title: `${aiCount} cards generated and added to deck` });
139	    } catch (err) {
140	      toast({ title: "AI generation failed", description: err instanceof Error ? err.message : String(err), variant: "destructive" });
141	    } finally {
142	      setGenerating(false);
143	    }
144	  };
145	
146	  const CellText = ({ cardId, field, value, placeholder }: { cardId: number; field: EditCell["field"]; value: string; placeholder?: string }) => {
147	    const isEditing = editingCell?.cardId === cardId && editingCell.field === field;
148	    if (isEditing) {
149	      return (
150	        <Input
151	          autoFocus
152	          value={editValue}
153	          onChange={e => setEditValue(e.target.value)}
154	          onBlur={commitEdit}
155	          onKeyDown={e => { if (e.key === "Enter") commitEdit(); if (e.key === "Escape") setEditingCell(null); }}
156	          className="h-7 text-xs bg-input border-primary/40 px-2 w-full"
157	        />
158	      );
159	    }
160	    return (
161	      <div
162	        className="min-h-[28px] px-2 py-1 text-xs cursor-text rounded hover:bg-primary/5 border border-transparent hover:border-primary/20 transition-colors truncate"
163	        onClick={() => startEdit(cardId, field, value)}
164	        title={value || placeholder}
165	      >
166	        {value || <span className="text-muted-foreground/30 italic">{placeholder ? `${placeholder}…` : "—"}</span>}
167	      </div>
168	    );
169	  };
170	
171	  const subtypeCounts = cards.reduce<Record<string, number>>((acc, c) => {
172	    const k = c.subtype || "Uncategorized";
173	    acc[k] = (acc[k] || 0) + 1;
174	    return acc;
175	  }, {});
176	
177	  return (
178	    <div className="mt-3 border border-border/50 rounded-lg overflow-hidden bg-background/30">
179	      {/* Header */}
180	      <div className="flex items-center justify-between px-4 py-2.5 bg-muted/10 border-b border-border/40">
181	        <div className="flex items-center gap-2 flex-wrap">
182	          <span className="text-xs font-semibold text-white flex items-center gap-1.5">
183	            <Hash className="w-3.5 h-3.5 text-indigo-400" /> Cards in this deck
184	          </span>
185	          <span className="text-[10px] text-muted-foreground bg-muted/40 px-1.5 py-0.5 rounded">{cards.length} total</span>
186	          {Object.entries(subtypeCounts).slice(0, 4).map(([k, c]) => (
187	            <span key={k} className="text-[10px] text-muted-foreground">{k}: {c}</span>
188	          ))}
189	        </div>
190	        <div className="flex gap-1">
191	          <Button variant="ghost" size="sm" className="h-6 text-xs gap-1 text-primary hover:bg-primary/10" onClick={() => { setShowAI(v => !v); setShowAddForm(false); }}>
192	            <Sparkles className="w-3 h-3" /> AI Generate
193	          </Button>
194	          <Button variant="ghost" size="sm" className="h-6 text-xs gap-1" onClick={() => exportDeckCSV(deck.name, cards)} disabled={cards.length === 0}>
195	            <Download className="w-3 h-3" /> CSV
196	          </Button>
197	          <Button variant="ghost" size="sm" className="h-6 text-xs gap-1" onClick={() => { setShowAddForm(v => !v); setShowAI(false); }}>
198	            <Plus className="w-3 h-3" /> Add card
199	          </Button>
200	        </div>
201	      </div>
202	
203	      {/* AI Generate panel */}
204	      {showAI && (
205	        <div className="px-4 py-3 border-b border-border/40 bg-primary/5 space-y-2">
206	          <div className="flex items-center justify-between">
207	            <p className="text-xs font-medium text-primary flex items-center gap-1"><Sparkles className="w-3 h-3" /> Batch Generate Cards</p>
208	            <button onClick={() => setShowAI(false)}><X className="w-3.5 h-3.5 text-muted-foreground hover:text-white" /></button>
209	          </div>
210	          <div className="flex gap-2">
211	            <Input
212	              value={aiPrompt}
213	              onChange={e => setAiPrompt(e.target.value)}
214	              onKeyDown={e => { if (e.key === "Enter") handleAIGenerate(); }}
215	              placeholder={`e.g. "mix of attack, spell, and item cards for ${deck.name}"…`}
216	              className="h-8 text-xs bg-input flex-1"
217	            />
218	            <Select value={aiCount.toString()} onValueChange={v => setAiCount(parseInt(v))}>
219	              <SelectTrigger className="h-8 w-16 text-xs bg-input shrink-0"><SelectValue /></SelectTrigger>
220	              <SelectContent>{[3, 5, 8, 12, 20].map(n => <SelectItem key={n} value={n.toString()}>{n}</SelectItem>)}</SelectContent>
221	            </Select>
222	          </div>
223	          <Button size="sm" onClick={handleAIGenerate} disabled={!aiPrompt || generating} className="w-full h-7 text-xs gap-1.5">
224	            {generating ? <><Loader2 className="w-3 h-3 animate-spin" /> Generating…</> : <><Sparkles className="w-3 h-3" /> Generate {aiCount} cards</>}
225	          </Button>
226	        </div>
227	      )}
228	
229	      {/* Add card form */}
230	      {showAddForm && (
231	        <div className="px-4 py-3 border-b border-border/40 bg-card/50 space-y-2">
232	          <p className="text-xs font-medium text-white">New card</p>
233	          <div className="grid grid-cols-2 gap-2">
234	            <div>
235	              <Label className="text-[10px] text-muted-foreground">Name *</Label>
236	              <Input
237	                value={newCard.name}
238	                onChange={e => setNewCard(c => ({ ...c, name: e.target.value }))}
239	                className="h-7 text-xs bg-input"
240	                autoFocus
241	                onKeyDown={e => { if (e.key === "Enter") handleAddCard(); }}
242	              />
243	            </div>
244	            <div>
245	              <Label className="text-[10px] text-muted-foreground">Subtype</Label>
246	              <Select value={newCard.subtype || "__none__"} onValueChange={v => setNewCard(c => ({ ...c, subtype: v === "__none__" ? "" : v }))}>
247	                <SelectTrigger className="h-7 text-xs bg-input"><SelectValue placeholder="—" /></SelectTrigger>
