import {
  PHYSICAL_TYPES, WORLD_TYPES, COMPONENT_SUBTYPES, getMeta, getStatusMeta, STATUS_OPTIONS,
  type ComponentType,
} from "@/lib/game-component-types";
import {
  ENTITY_TEMPLATES, buildStatsForTier, previewStatValue, TIER_LABELS,
  type EntityTemplate,
} from "@/lib/entity-templates";
import { Sheet, SheetContent, SheetHeader, SheetTitle, SheetDescription } from "@/components/ui/sheet";
import { CardStudio } from "./card-studio";

// ─── Color picker presets (#53) ─────────────────────────────────────────────

const CARD_COLORS = [
  "#6366f1", "#8b5cf6", "#a855f7", "#ec4899",
  "#ef4444", "#f97316", "#eab308", "#22c55e",
  "#14b8a6", "#06b6d4", "#3b82f6", "#64748b",
];

// ─── Relationship verbs ──────────────────────────────────────────────────────

const RELATIONSHIP_VERBS = [
  "counters", "requires", "spawns", "upgrades", "drops",
  "part-of", "enables", "enemy-of", "ally-of", "is-a",
] as const;

// ─── Property templates by component type ────────────────────────────────────

type PropTemplate = { name: string; dataType: string; defaultValue: string };
const PROPERTY_TEMPLATES: Record<string, PropTemplate[]> = {
  Enemy:    [{ name:"Health", dataType:"number", defaultValue:"10" }, { name:"Damage", dataType:"number", defaultValue:"5" }, { name:"Speed", dataType:"number", defaultValue:"3" }, { name:"XP Reward", dataType:"number", defaultValue:"10" }],
  Meeple:   [{ name:"Health", dataType:"number", defaultValue:"3" }, { name:"Movement", dataType:"number", defaultValue:"2" }, { name:"Armor", dataType:"number", defaultValue:"0" }],
  Card:     [{ name:"Cost", dataType:"number", defaultValue:"2" }, { name:"Power", dataType:"number", defaultValue:"1" }, { name:"Defense", dataType:"number", defaultValue:"0" }],
  Item:     [{ name:"Weight", dataType:"number", defaultValue:"1" }, { name:"Value", dataType:"number", defaultValue:"5" }, { name:"Durability", dataType:"number", defaultValue:"100" }],
  Location: [{ name:"Capacity", dataType:"number", defaultValue:"4" }, { name:"Danger", dataType:"number", defaultValue:"2" }, { name:"Resources", dataType:"number", defaultValue:"1" }],
  Event:    [{ name:"Duration", dataType:"number", defaultValue:"1" }, { name:"Severity", dataType:"number", defaultValue:"2" }],
  Faction:  [{ name:"Strength", dataType:"number", defaultValue:"5" }, { name:"Influence", dataType:"number", defaultValue:"3" }, { name:"Size", dataType:"number", defaultValue:"10" }],
  Resource: [{ name:"Quantity", dataType:"number", defaultValue:"0" }, { name:"Max", dataType:"number", defaultValue:"10" }],
  Token:    [{ name:"Value", dataType:"number", defaultValue:"1" }],
  Ability:  [{ name:"Power", dataType:"number", defaultValue:"5" }, { name:"Cost", dataType:"number", defaultValue:"2" }, { name:"Cooldown", dataType:"number", defaultValue:"0" }],
};

// ─── Helpers ────────────────────────────────────────────────────────────────

function parseStats(raw: string | null | undefined): { key: string; val: string }[] {
  if (!raw) return [];
  return raw
    .split(/[/\n]/)
    .map((s) => s.trim())
    .filter(Boolean)
    .map((s) => {
      const m = s.match(/^([^:=0-9]+?)\s*[:=]?\s*(\S+)\s*$/);
      if (m) return { key: m[1].trim(), val: m[2] };

