// ── Deck Studio hero section ──────────────────────────────────────────────────

function DeckStudioSection({ projectId, allEntities, onRefresh }: {
  projectId: number;
  allEntities: Entity[];
  onRefresh: () => void;
}) {
  const { toast } = useToast();
  const createEntity = useCreateEntity();
  const decks = useMemo(() => allEntities.filter(e => e.type === "Deck"), [allEntities]);
  const [selectedDeckId, setSelectedDeckId] = useState<number | null>(null);
  const [showNewDeck, setShowNewDeck] = useState(false);
  const [newDeckName, setNewDeckName] = useState("");
  const [newDeckSubtype, setNewDeckSubtype] = useState("Custom");

  const DECK_SUBTYPES = ["Item Deck", "Event Deck", "Encounter Deck", "Spell Deck", "Quest Deck", "Custom"];

  // Auto-select first deck when decks load
  const selectedId = selectedDeckId ?? decks[0]?.id ?? null;

  const selectedDeck = decks.find(d => d.id === selectedId) ?? null;
  const cards = useMemo(
    () => allEntities.filter(e => e.type === "Card" && e.parentEntityId === selectedId),
    [allEntities, selectedId]
  );

  const handleCreateDeck = async () => {
    if (!newDeckName.trim()) return;
    try {
      const deck = await createEntity.mutateAsync({
        projectId,
        data: { name: newDeckName.trim(), type: "Deck", subtype: newDeckSubtype },
      });
      setNewDeckName("");
      setShowNewDeck(false);
      setSelectedDeckId(deck.id);
      onRefresh();
      toast({ title: `Deck "${deck.name}" created` });
    } catch {
      toast({ title: "Could not create deck", variant: "destructive" });
    }
  };

  return (
    <div className="border border-border rounded-xl overflow-hidden bg-card/40">
      {/* Section header */}
      <div className="flex items-center justify-between px-4 py-3 border-b border-border bg-card/60">
        <div className="flex items-center gap-2">
          <TableIcon className="h-4 w-4 text-indigo-400" />
          <span className="font-semibold text-sm">Card & Deck Builder</span>
          <span className="text-xs text-muted-foreground">— design your decks, add cards, track playtest status</span>
        </div>
      </div>

      {decks.length === 0 && !showNewDeck ? (
        <div className="py-10 text-center space-y-3">
          <p className="text-sm text-muted-foreground">No decks yet.</p>
          <p className="text-xs text-muted-foreground/60">Create a deck to start building cards.</p>
          <Button size="sm" onClick={() => setShowNewDeck(true)} className="gap-1.5">
            <Plus className="h-3.5 w-3.5" /> Create first deck
          </Button>
        </div>
      ) : (
        <div className="p-4 space-y-3">
          {/* Deck picker + new deck */}
          <div className="flex items-center gap-2 flex-wrap">
            {decks.map(deck => {
              const deckCards = allEntities.filter(e => e.type === "Card" && e.parentEntityId === deck.id);
              return (
                <button
                  key={deck.id}
                  onClick={() => setSelectedDeckId(deck.id)}
                  className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-sm border transition-all ${
                    selectedId === deck.id
                      ? "bg-indigo-600/20 border-indigo-500/50 text-indigo-300 font-medium"
                      : "bg-card border-border text-muted-foreground hover:text-foreground hover:border-border/80"
                  }`}
                >
                  🃏 {deck.name}
                  <span className="text-[10px] opacity-60">{deckCards.length}</span>
                </button>
              );
            })}
            <button
              onClick={() => setShowNewDeck(v => !v)}
              className="flex items-center gap-1 px-3 py-1.5 rounded-lg text-sm border border-dashed border-border text-muted-foreground hover:text-foreground hover:border-border/80 transition-all"
            >
              <Plus className="h-3.5 w-3.5" /> New deck
            </button>
          </div>

          {/* New deck form */}
          {showNewDeck && (
            <div className="flex items-end gap-2 p-3 bg-muted/20 rounded-lg border border-border/50">
              <div className="flex-1">
                <Label className="text-[10px] text-muted-foreground mb-1 block">Deck name</Label>
                <Input
                  value={newDeckName}
                  onChange={e => setNewDeckName(e.target.value)}
                  onKeyDown={e => { if (e.key === "Enter") handleCreateDeck(); }}
                  placeholder="e.g. Spell Deck, Item Deck…"
                  className="h-8 text-sm bg-input"
                  autoFocus
                />
              </div>
              <div className="w-36 shrink-0">
                <Label className="text-[10px] text-muted-foreground mb-1 block">Type</Label>
                <Select value={newDeckSubtype} onValueChange={setNewDeckSubtype}>
                  <SelectTrigger className="h-8 text-xs bg-input"><SelectValue /></SelectTrigger>
                  <SelectContent>
                    {DECK_SUBTYPES.map(s => <SelectItem key={s} value={s}>{s}</SelectItem>)}
                  </SelectContent>
                </Select>
              </div>
              <Button size="sm" onClick={handleCreateDeck} disabled={!newDeckName.trim() || createEntity.isPending} className="h-8 gap-1 shrink-0">
                {createEntity.isPending ? <Loader2 className="w-3 h-3 animate-spin" /> : <Plus className="w-3 h-3" />}
                Create
              </Button>
              <Button size="sm" variant="ghost" onClick={() => setShowNewDeck(false)} className="h-8 shrink-0">Cancel</Button>
            </div>
          )}

          {/* Card Studio for selected deck */}
          {selectedDeck && (
            <CardStudio
              projectId={projectId}
              deck={selectedDeck}
              cards={cards}
              onRefresh={onRefresh}
            />
          )}
        </div>
      )}
    </div>
  );
}

